root=Path(__file__).resolve().parents[1];fig=root/'figures'
OUT=root/'paceval_Biomanufacturing_PAT_Whitepaper_EN.pdf'
pdfmetrics.registerFont(TTFont('DVS','/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'))
pdfmetrics.registerFont(TTFont('DVS-Bold','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'))
C=HexColor('#15364a');ACC=HexColor('#158b84');GREY=HexColor('#5f7079');BG=HexColor('#e9f5f3');RED=HexColor('#b95553');W=500
ST={
 'title':ParagraphStyle('Title',fontName='DVS-Bold',fontSize=22,leading=29,textColor=C,spaceAfter=16),
 'subtitle':ParagraphStyle('Subtitle',fontName='DVS',fontSize=12,leading=17,textColor=GREY,spaceAfter=18),
 'h1':ParagraphStyle('H1',fontName='DVS-Bold',fontSize=15.4,leading=19,textColor=C,spaceBefore=11,spaceAfter=10),
 'h2':ParagraphStyle('H2',fontName='DVS-Bold',fontSize=10.7,leading=15,textColor=ACC,spaceBefore=9,spaceAfter=5),
 'body':ParagraphStyle('Body',fontName='DVS',fontSize=8.7,leading=13.6,textColor=C,spaceAfter=9),
 'small':ParagraphStyle('Small',fontName='DVS',fontSize=7.6,leading=11.2,textColor=GREY,spaceAfter=8),
 'caption':ParagraphStyle('Caption',fontName='DVS',fontSize=8.0,leading=11.3,textColor=GREY,spaceBefore=5,spaceAfter=13),
 'eq':ParagraphStyle('Equation',fontName='DVS',fontSize=9.0,leading=15,textColor=C,leftIndent=14,spaceBefore=5,spaceAfter=10),
 'table':ParagraphStyle('Table',fontName='DVS',fontSize=7.9,leading=11,textColor=C),
}
def P(s,style='body'):return Paragraph(s,ST[style])
def h(s):return P(s,'h1')
def sub(s):return P(s,'h2')
def para(s):return P(s)
def eq(s):return P(escape(s),'eq')
def br():return PageBreak()
def pic(name,maxw=495,maxh=295):
 p=fig/name; im=PILImage.open(p);iw,ih=im.size;scale=min(maxw/iw,maxh/ih);return RLImage(str(p),width=iw*scale,height=ih*scale)
def cap(s):return P(s,'caption')
def table(rows,widths=None):
 data=[[P(escape(str(x)),'table') for x in row] for row in rows]
 w=widths or [W/len(rows[0])]*len(rows[0]);t=Table(data,colWidths=w,hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BG),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,0),.7,ACC),('LINEBELOW',(0,1),(-1,-1),.25,HexColor('#d8e5e6')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7)]));return t
D=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=47,leftMargin=47,topMargin=50,bottomMargin=48,title='Biomanufacturing Process Analytical Technology with paceval',author='paceval Mathematical Research',subject='Original paceval MCP mathematical execution and bioreactor monitoring')
flow=[]
# COVER
flow.extend([Spacer(1,29),P('BIOMANUFACTURING PROCESS ANALYTICAL TECHNOLOGY','small'),P('Programmable Growth and Oxygen-Transfer Monitoring with paceval','title'),P('Reusable mathematical execution graphs for an illustrative fed-batch bioreactor, with independently checked model versions and transparent scientific boundaries.','subtitle'),pic('00_biomanufacturing_pat_hero.png',W,250),P('Concept illustration; not a computed research result.','small'),Spacer(1,12),HRFlowable(width='100%',thickness=1,color=ACC),Spacer(1,14),sub('RESEARCH OUTCOME'),para('Twenty-four distinct mathematical models and related analytical functions were executed through the original paceval MCP service (reported version 4.26). The evidence covers an 81-point sensor-state grid and 16 synthetic replay snapshots. All 515 retained ordinary numerical outputs passed an independent high-precision reference check.'),sub('PRECISE VERIFICATION BOUNDARY'),para('Eighteen printed TINC interval records were audited. Fifteen showed direct inclusion under an exact-binary-input interpretation; three collapsed printed score intervals require investigation using typed local SDK bounds. The C++ source passes syntax checks but could not be linked or executed without a compatible original Linux library. No GMP qualification is claimed.'),P('Scientific Research Demonstrator  |  14 November 2026','small'),br()])
# 1 INTRO
flow.extend([h('1. Industrial use case and current state of the art'),para('Modern biomanufacturing uses controlled bioreactors to cultivate microorganisms or mammalian cells for biologic products, enzymes and other valuable substances. Operators monitor substrates, viable or dry-cell biomass, pH, dissolved oxygen (DO), gases and feeding conditions. A process analytical technology (PAT) layer transforms these measurements into interpretable estimates, trends and alerts. Unlike a single sensor alarm, a mathematical monitoring layer can make explicit why a process is approaching a limitation.'),para('The focal scenario is a hypothetical fed-batch reactor producing a biological product. A set of synthetic process snapshots supplies substrate S, dissolved oxygen DO, biomass X, aeration effectiveness kLa and liquid feed F. A mathematical model calculates specific growth, substrate consumption, oxygen uptake (OUR), oxygen transfer (OTR) and instantaneous mass-balance slopes. Numerical guard expressions combine the estimated oxygen transfer capacity with a direct DO concentration threshold. The purpose is reproducible function evaluation, not the automatic adjustment of a physical reactor.'),sub('What industry uses today'),para('Established solutions combine process probes, off-gas analysis, Raman or near-infrared measurements, soft sensors, mechanistic or hybrid models, and manufacturing execution/quality systems. FDA PAT guidance (2004) encourages scientifically grounded process understanding. ICH Q13 (2022/2023) covers monitoring and control considerations for continuous manufacturing, including therapeutic proteins. Such references set a conceptual context and do not certify this software [1,2].'),para('A 2024 study considered real-time oxygen-uptake monitoring in CHO antibody-production reactors. Reviews published in 2025 and 2026 discuss in-situ bioreactor instrumentation, oxygen sensing and soft-sensor integration, along with calibration drift and model transportability challenges [3-6]. This project isolates the reusable mathematical expressions within that wider pipeline; it does not attempt to replace spectroscopy, instrumentation or a validated plant historian.'),sub('Research question'),para('Can the original paceval engine execute and reuse biologically meaningful kinetic, oxygen and fed-batch balance expressions, their versioned alternatives and explicit warning functions, while retaining an independently auditable numerical trail? The experiment answers that mathematical functional question for deterministic inputs. It does not assess actual product quality, cell viability or bioreactor dynamics against physical observations.'),br()])
# 2 model
flow.extend([h('2. Defined kinetic and mass-balance model'),para('The source WP 05 proposes Monod-type growth with oxygen limitation, substrate uptake, constant cell-specific oxygen demand and a gas-liquid oxygen balance. The current study retains those four ideas and adds a separately versioned substrate-inhibition/growth-coupled oxygen-uptake scenario, two process constraints, material-balance rates and analytical derivatives.'),sub('Version v1: saturating growth'),eq('mu1 = umax * S/(Ks + S) * DO/(Ko + DO)'),eq('rS1 = mu1 * X / Yxs       OUR1 = qO2 * X'),sub('Version v2: hypothetical substrate-inhibition extension'),eq('mu2 = umax * S/(Ks + S + S^2/Ki) * DO/(Ko + DO)'),eq('OUR2 = (qO2 + qG*mu2) * X       rS2 = mu2 * X / Yxs'),para('These are illustrative parameterizations, not identified CHO kinetic laws. The v2 formulation has a potentially nonmonotonic substrate response. Its constants were chosen for an algebraic demonstration and must not be interpreted as organism-specific values.'),sub('Fed-batch instantaneous mass-balance rates'),eq('OTR = kLa * (DOstar - DO)'),eq('dX/dt = (mu - F/V) * X'),eq('dS/dt = (F/V)*(Sfeed - S) - mu*X/Yxs'),eq('dDO/dt = OTR - OUR - (F/V)*DO'),para('V is the current reactor volume, assumed supplied per snapshot. No time integration is performed on the synthetic replay. Feed is assumed oxygen-free, there is no effluent, and kLa is an effective lumped coefficient. In a physical simulation V changes with feed, and gas, pH, metabolic shifts and volume constraints require additional equations.'),sub('Dimensions and domains'),para('S and Sfeed are g substrate/L; X is g dry biomass/L; DO and DOstar are g oxygen/L. Growth rates are 1/h, F is L/h, V is L, kLa is 1/h, Yxs is g biomass/g substrate, qO2 is g oxygen/(g biomass·h), and qG is g oxygen/g biomass. Ks, Ko and Ki carry concentration units as appropriate. The required positive denominators and DOstar greater than DO are validated on the host before evaluating any graph.'),br()])
# 3 interpretable guards
flow.extend([h('3. Oxygen-limitation monitoring and constraints'),para('The oxygen driving force (DOstar - DO) and transfer coefficient kLa produce a rate OTR. A rate-only oxygen margin is not a complete dissolved-oxygen safety rule: OTR may exceed OUR while the current DO is already below an operating floor.'),eq('Moxygen_v = OTR - OUR_v           [g O2 / L / h]'),eq('MDO = DO - DOmin                 [g O2 / L]'),eq('Score_v = min(MDO, tau * Moxygen_v)  [g O2 / L]'),eq('Guard_v = (DO >= DOmin) AND (Moxygen_v >= 0) AND (S >= 0)'),para('A host-defined monitoring decision interprets the paceval guard. Equality at the boundary counts as mathematically satisfying the non-strict >= constraints. An adequate positive score only means the deliberately chosen mathematical conditions hold for the given inputs. It is not an independent industrial acceptance or product-release statement.'),sub('Analytical sensitivities and model comparisons'),eq('d(mu2)/dS = umax * DO/(Ko+DO) * (Ks-S^2/Ki)/(Ks+S+S^2/Ki)^2'),eq('d(dDO/dt)/d(kLa) = DOstar - DO'),eq('kLa_required_v2 = OUR2/(DOstar - DO)'),eq('Delta_mu = mu2 - mu1'),para('The host is responsible for domain checks, input schema, units, ordering, graph-handle lifecycle and stateful procedures. The engine executes all explicitly registered formulas, including composite scoring, comparisons, sensitivity functions, minimum/maximum operators and logical guards. No automatic differentiation is claimed.'),sub('Why versioning matters'),para('The experiment retains two independent persistent graph versions instead of mutating a single expression. Their differences are scientifically interpretable: v1 increases saturatingly with substrate; v2 can decline at higher substrate due to an explicitly added inhibition term. More flexible formula deployment does not make either model automatically correct for a production strain.'),br()])
# 4 implementation
flow.extend([h('4. Actually executed paceval graph architecture'),pic('01_PAT_architecture_schematic.png',W,175),cap('Figure 1. Conceptual architecture. This schematic is not an executed bioreactor measurement.'),para('The live paceval MCP service reports version 4.26 in the recorded responses. Twenty-four independently registered mathematical graphs were evaluated together for 81 parameter-grid cases and 16 synthetic replay cases. Selected graphs were reused for a further 16-point verification call. Three interval-enabled graphs supplied six additional points each. A separate operator batch tested infix minimum/maximum, logical expressions, signed remainder and mathematical modulo.'),table([['Functional group','paceval graph responsibility','Host responsibility'],['Growth & consumption','v1/v2 mu, rS, dX, dS','Units, replay phase and data schema'],['Oxygen rates','OUR v1/v2, OTR, dDO','Validate DOstar > DO and finite values'],['Quality rules','Margins, 0/1 guards and min score','Define REVIEW/INVESTIGATE semantics'],['Model analysis','Sensitivity, delta and kLa requirement','Select and document model version'],['Numerical audit','TINC output in remote execution','High-precision checks and traceability']],[130,200,171]),sub('Local C++ integration'),para('The supplied C++17 project includes the original paceval_main.h and paceval_main.cpp files without replacing the engine. It implements paceval_CreateComputation, scalar checks, per-graph batch checks, multi-graph batch evaluation, error checking, TINC output fields and resource cleanup. Numeric input and output are delegated to paceval_dConvertStringToFloat and paceval_dConvertFloatToString, after a strict decimal-literal grammar has rejected expression text in CSV fields. CMake requires a separately supplied ABI-compatible Linux runtime and does not redistribute a shared library.'),para('This C++ code was syntax-checked with a standard Linux C++ compiler. It was not linked, executed or CTest-validated because the compatible original shared runtime was not available. The measured numerical results in this paper come from real remote MCP calls, never from an unexecuted local binary.'),br()])
# 5 data
flow.extend([h('5. Deterministic research workload and execution evidence'),para('All measurements are synthetically specified. The 16 replay rows represent a sequence of candidate sensor snapshots across distinct hypothetical feeding and oxygen-transfer phases; they are NOT a dynamically integrated biological trajectory. The 81-state grid varies biomass and dissolved-oxygen concentration while holding the other inputs fixed. Both data sets use explicit concentration and flow units and retain the original input text separately from the generated numerical output.'),table([['Executed scope','Verified record'],['Original v1/v2 and supporting graph registrations','24 registered; 24 executed'],['Parameter grid','81 cases × 24 graphs = 1,944 graph-point evaluations'],['Synthetic replay','16 cases × 24 graphs = 384 graph-point evaluations'],['Additional replay selections','6 reused graphs × 16 cases = 96 evaluations'],['Interval-enabled sub-study','3 additional graphs × 6 cases = 18 interval outputs'],['Ordinary independent checks','515 retained recorded values; all passed'],['Printed TINC interval checks','15 inclusive; 3 unresolved from printed endpoints'],['Local SDK/CTest','Source syntax checked; runtime execution unavailable']],[258,243]),sub('Interpretation of a representative snapshot'),para('At replay hour 10, the synthetic inputs contain DO = 0.0016 g/L and biomass X = 6.5 g dry mass/L. paceval evaluates v2 oxygen uptake as approximately 0.30129 g oxygen/L/h and oxygen transfer as 0.352 g oxygen/L/h. The resulting positive oxygen margin does not eliminate the need for a separate concentration floor. At hours 11 and 12, the supplied DO values fall below the illustrative DOmin of 0.0015 g/L even though oxygen transfer remains adequate. At hour 13, equality at DOmin yields a zero composite score and a true non-strict logical guard.'),para('All rates and decision thresholds are demonstrator inputs. The synthetic time index must not be mistaken for kinetic integration, predictive process behavior, process capability, or a validated QbD design space.'),br()])
# figures pages
flow.extend([h('6. Growth and oxygen-transfer results'),pic('02_growth_model_versions.png',W,260),cap('Figure 2. paceval MCP v4.26 growth-model values. The distinct v1/v2 responses show the functional effect of the model version, not experimental fit quality.'),pic('03_oxygen_transfer_uptake.png',W,260),cap('Figure 3. OTR and two OUR versions returned by paceval for the synthetic snapshot series.'),br()])
flow.extend([h('7. Process margins and monitoring decisions'),pic('04_oxygen_balance_margin.png',W,260),cap('Figure 4. Independent paceval margins quantify the difference between gas-liquid oxygen transfer and cellular uptake.'),pic('05_DO_limit_guard.png',W,260),cap('Figure 5. Synthetic DO input with the v2 paceval-computed logical guard. The guard becomes false when the DO input is below the selected illustrative floor.'),br()])
flow.extend([h('8. Multidimensional process-state analysis'),pic('06_oxygen_margin_parameter_map.png',W,405),cap('Figure 6. The 81 actually executed paceval points are displayed as a parameter map with the zero-margin contour. The dataset is synthetic, and interpolation between samples is illustrative only.'),para('The parameter grid demonstrates that more biomass demands greater oxygen-transfer capacity, while changes in dissolved oxygen modify both mass-transfer driving force and growth-coupled oxygen uptake. The zero-margin line is a mathematical limit of the stipulated reduced-order model, not a production-approved process boundary.'),br()])
flow.extend([h('9. Composite score surface'),pic('07_score_surface_3d.png',W,425),cap('Figure 7. Recorded paceval v2 composite scores on the same 81 state combinations. Positive and negative surface values encode the chosen mathematical constraints after scaling the oxygen-rate margin by the illustrative horizon tau.'),para('The min operator is executed inside paceval. The surface exposes non-smooth transitions between DO-concentration limitation and transfer-rate limitation. The transition is a model and policy feature, not evidence of a discontinuous cell-physiology response.'),br()])
flow.extend([h('10. Required oxygen transfer and sensitivity'),pic('08_required_kla.png',W,250),cap('Figure 8. Real paceval evaluations of the kLa requirement under v2 and the supplied phase-specific kLa input.'),pic('09_growth_sensitivity.png',W,250),cap('Figure 9. Explicit analytical paceval expression for substrate sensitivity in v2. The negative values in these synthetic snapshots reflect substrate-inhibition behavior.'),br()])
flow.extend([h('11. Trusted interval output and independent verification'),pic('10_tinc_margin_width.png',W,235),cap('Figure 10. Widths of reported TINC interval bounds for six oxygen-margin checks. These are transmitted numerical bounds from remote paceval, not a claim of global parameter-interval certification.'),para('A separate independent 90-digit mpmath implementation uses the exact binary64 values of all incoming numerical parameters, not the same paceval formula strings. All 515 ordinary retained numerical outputs in the replay and grid audit passed their predefined comparison rule. For TINC bounds, 15 of the 18 reported decimal intervals directly enclosed the corresponding independently computed value. Three v2 score cases were returned as identical printed decimal lower and upper endpoints at the selected threshold. The exact-binary-input reference lies outside these literal decimal endpoints. They remain unresolved until typed double bounds from the local SDK are retrieved.'),para('This finding is not disguised as full TINC certification or evidence that the engine’s underlying binary interval implementation is invalid. The available remote textual output is insufficient to distinguish an interval-computation defect from a serialization/rounding limitation. Local ABI-compatible execution, raw binary interval archives, and directed-rounding regression tests are a necessary follow-up.'),br()])
# references
flow.extend([h('12. Scientific limitations, reproducibility and references'),sub('Established facts versus hypotheses'),para('What is executed: reusable paceval graph evaluation, v1/v2 kinetic expressions, oxygen rates, fed-batch instantaneous derivative expressions, composite scoring, logical 0/1 conditions, a parameter grid, a synthetic replay and independently checked recorded results. What is not established: accurate behavior for a specific mammalian cell line, sensor-calibrated parameter estimates, validated oxygen-transfer identification, closed-loop controller stability, GMP compliance, process capability or a release-by-exception decision.'),para('The baseline is a reduced-order mathematical model. Oxygen concentrations, growth rate, feed composition, respiration, process volume and mass transfer interact with hidden states, adaptation, pH, by-products and gas-liquid dynamics in real vessels. Quantitative scaling requires industrial sensor validation, identifiability analysis, uncertainty models, dynamic integration and domain-appropriate acceptance criteria. FDA and ICH guidance should be interpreted within the full applicable quality system; this research is not a regulatory submission.'),sub('Reproduction'),para('Run <font name="DVS-Bold">python validation/high_precision_reference.py</font> to regenerate the independent audit. Run <font name="DVS-Bold">python scripts/make_figures.py</font> to regenerate scientific graphics from the recorded remote paceval files. To execute the original local SDK route, provide an ABI-compatible x86-64 Linux library and run <font name="DVS-Bold">bash scripts/build_and_test.sh /absolute/path/libpaceval_linux_sharedLIB.so</font>. The latter remains an unexecuted test path in the supplied release. API signatures should be checked against the included original SDK files.'),sub('Selected external references'),P('[1] FDA, <i>PAT: A Framework for Innovative Pharmaceutical Development, Manufacturing, and Quality Assurance</i>, 2004. <link href="https://www.fda.gov/regulatory-information/search-fda-guidance-documents/pat-framework-innovative-pharmaceutical-development-manufacturing-and-quality-assurance" color="#158b84">FDA guidance</link>.','small'),P('[2] FDA / ICH Q13, <i>Continuous Manufacturing of Drug Substances and Drug Products</i>, 2022-2023. <link href="https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q13-continuous-manufacturing-drug-substances-and-drug-products" color="#158b84">Q13 guidance</link>.','small'),P('[3] <i>A real-time oxygen uptake rate monitoring approach suitable for the antibody production process</i>, 2024. <link href="https://www.sciencedirect.com/science/article/pii/S1369703X2400250X" color="#158b84">Journal link</link>.','small'),P('[4] <i>Benchmarking and Trends Around In-situ and Ex-situ Sensors in Bioreactors</i>, 2025. <link href="https://doi.org/10.3303/CET25117018" color="#158b84">DOI</link>.','small'),P('[5] <i>Optical Fiber pH and Dissolved Oxygen Sensors for Bioreactor Monitoring: A Review</i>, published 2025 (2026 issue). <link href="https://doi.org/10.3390/s26010010" color="#158b84">DOI</link>.','small'),P('[6] <i>Less Is More: Practical Insights into Multivariate Regression Models for Raman Spectroscopy in Bioprocess Monitoring</i>, 2025. <link href="https://pubmed.ncbi.nlm.nih.gov/41420293/" color="#158b84">PubMed</link>.','small'),P('[7] paceval Mathematical Engine, <link href="https://paceval.com/api/" color="#158b84">Original API reference (4.25 documented)</link>. Live MCP service reported v4.26 for this study.','small')])

def footer(canvas,doc):
 canvas.saveState();w,h=A4
 canvas.setStrokeColor(HexColor('#d8e9e6'));canvas.line(47,44,w-47,44)
 canvas.setFont('DVS',7);canvas.setFillColor(GREY)
 canvas.drawString(47,31,'paceval | Biomanufacturing PAT | Research demonstrator | 2026')
 canvas.drawRightString(w-47,31,f'{doc.page}')
 canvas.restoreState()
D.build(flow,onFirstPage=footer,onLaterPages=footer)
print('Created report',OUT,'size',OUT.stat().st_size)
